mapper.select:
SELECT distinct TABLE_ID AS id, TABLE_NAME AS text FROM BOK_TABLELIST BT where 1=1
and (TABLE_NAME like concat(concat('%', #{search,jdbcType=VARCHAR}),'%') or TABLE_id like concat(concat('%', #{search,jdbcType=VARCHAR}),'%'))
and BOOKSET_ID = #{booksetId}

mapper.sql:
WHERE 1 = 1
AND BS.BOOKSET_ID = #{booksetId}

    AND BS.SCENE_NODE_ID LIKE 
    nvl((SELECT SCENE_NODE_ID
        FROM BOK_SCENECONFIG
        WHERE NODE_ID = #{ACCOUNTEVENTS}
        AND BOOKSET_ID = #{booksetId}
        AND NODE_VALUE = #{nodeId})
        ,'#无该节点内容#')||'%'
